// Left side menu: a top-left toggle button opens a full-height drawer, and a
// gear at the drawer's bottom-right swaps its body to the settings page.
//
// Built in JS rather than markup because dist/index.html is generated by
// build.mjs and has already drifted from src/index.html — one source here keeps
// dev and dist in step. The icons are v1's, lifted from game/ui.js.

import {
  PLAYER_COLORS,
  SHADOW_LABELS,
  getPlayerColor,
  getPlayerName,
  getShadowMode,
  resolveShadowMode,
  setPlayerColor,
  setPlayerName,
  setShadowMode,
  shadowTier,
} from './settings.js';

const ICON_BARS = '<svg width="100%" height="100%" viewBox="0 0 26 26"><path style="fill-opacity:1;stroke:none;stroke-width:.260162;stroke-dasharray:none;stroke-opacity:.998532" d="M13.834 7.576s9.03-.316 9.707-.854c.676-.539 1.076-1.46 1.076-1.46s-.348 2.096-.35 3.038c0 .94.495 2.816.495 2.816s-.975-1.292-1.452-1.603c-.476-.31-8.693-.457-8.693-.457l-1.67-.002s-9.018.19-9.7.37c-.68.181-1.988 1.51-1.988 1.51s.51-1.739.63-2.693c.12-.953-.65-2.89-.65-2.89s1.323 1.115 2.314 1.701c.99.586 8.564.506 8.564.506zM1.121 14.024s.755 1.26 1.838 1.938c1.082.676 9.677.33 9.677.33l1.674.038s8.009-.135 8.81-.38c.798-.244 1.669-1.478 1.669-1.478s-.375 2.046-.353 2.954c.02.907.443 2.919.443 2.919s-.649-1.273-1.469-1.968c-.822-.696-9.916-.591-9.916-.591l-1.711-.004s-7.573.677-8.35 1.154c-.776.477-2.09 1.801-2.09 1.801s.819-2.034.668-3.154c-.15-1.12-.89-3.559-.89-3.559z"/></svg>';

const ICON_GEAR = '<svg width="100%" height="100%" viewBox="0 0 99 99"><path style="fill:none;stroke-width:5.7247;stroke-linecap:round;stroke-linejoin:miter;stroke-dasharray:none;stroke-opacity:1" d="M19.848 32.659c-1.806-1.905-4.302-3.979-3.715-6.864.587-2.886 3.377-4.255 5.047-6.328 2.445-2.1 4.659-5.56 7.23-6.445 2.572-.885 4.303.334 5.625 2.136 1.444 2.713 4.159.962 5.743-.022 1.584-.983.24-3.364.553-4.91.847-2.783 3.137-3.896 6.53-3.612 3.393.285 8.163-.171 12.152.131 2.662.855 3.88 3.565 3.551 6.178-.847 2.877 2.343 3.544 4.249 3.831 1.906.287 2.703-3.106 4.718-3.6 2.318-.704 4.694.416 6.074 2.332 2.76 2.844 5.757 5.526 8.373 8.47 1.432 2.208.843 5.306-1.37 6.84-2.75 1.304-.863 3.523-.202 5.424.56 1.77 3.223.504 4.69.965 2.867.574 4.58 3.565 4.027 6.362-.087 4.144.173 8.37-.129 12.463-.903 2.728-3.739 3.794-6.36 3.4-2.815-.855-3.66 2.272-3.701 4.4-.044 2.129 3.832 3.143 3.715 6.158-.116 3.015-3.148 4.714-4.856 6.902-2.183 2.054-4.186 4.389-6.481 6.268-2.39 1.178-5.253.166-6.771-1.984-1.428-2.729-3.793.123-5.917.4M19.98 80.1c-5.245 1.61-7.395.366-8.912-3.324-1.517-3.69-5.408-9.343-.99-11.256 4.418-1.913 1.252-5.106-2.313-5.849-3.565-.743-1.383-5.87-.649-8.652.595-3.907 3.17-8.828 7.766-7.428 4.596 1.401 2.93-3.363 1.658-6.44-1.272-3.076 3.584-4.967 6.12-6.444 2.633-1.203 6.81-5.717 8.635-2.048 1.825 3.669 6.523 4.471 7.034.12.512-4.351 5.305-2.722 7.898-1.583 2.61.841 5.56 1.053 7.88 2.547 2.932 2.642-.63 8.371 3.075 8.724 3.705.354 5.675-3.05 7.805-.139 1.775 3.475 4.201 6.704 5.57 10.36.73 4.216-6.377 5.791-3.895 8.755 2.481 2.963 6.003 1.783 5.552 5.261-1.079 3.69-1.956 7.472-3.179 11.132-2.418 3.981-8.885-.369-9.17 3.624-.287 3.992 3.078 6.539-.7 8.185-3.041 1.654-6.004 3.484-9.102 5.008-4.584 1.5-6.762-6.63-9.566-3.565-2.803 3.065-1.815 5.694-4.947 5.31-3.62-.996-7.274-1.972-11.295-3.579-4.021-1.606.97-10.329-4.275-8.72zm30.24-22.711c.178 1.042.34 2.142.14 3.18-.377 1.97-.998 3.998-2.263 5.56-.794.98-1.716 1.896-2.78 2.576-2.67 1.707-6.104 2.281-9.212 1.467h0c-1.337-.451-2.836-.829-3.865-1.813-1.038-.991-2.251-1.885-2.992-3.108-1.627-2.687-2.132-6.068-1.269-9.143 1.01-3.593 3.887-6.46 7.381-7.759 1.176-.437 2.344-.556 3.568-.529 1.275.03 2.572.092 3.785.513"/></svg>';

// Accent colours match v1's rt.css (aqua hover, darkmagenta active).
const CSS = `
/* Above the drawer, or it is unreachable once the drawer covers the corner. */
#menu_b { position: fixed; top: 0; left: 0; width: 24px; height: 24px; padding: 4px; fill: #fff; opacity: .42; cursor: pointer; z-index: 10003; }
#menu_b:hover { fill: aqua; opacity: 1; }
#menu_b:active { fill: darkmagenta; }
/* Opaque: the status line and lobby button sit underneath. */
#side_menu { position: fixed; top: 0; left: 0; bottom: 0; width: 260px; z-index: 10002; display: none; flex-direction: column; box-sizing: border-box; padding: 34px 14px 44px; background: #0c0f14; border-right: 1px solid #2a3140; font-size: 13px; }
#side_menu.is-open { display: flex; }
#side_menu h2 { margin: 0 0 12px; font-size: 15px; font-weight: 600; }
#side_menu .page { display: none; flex: 1; overflow-y: auto; overflow-x: hidden; }
#side_menu .page.is-active { display: block; }
#side_menu .row { margin-bottom: 14px; }
#side_menu label { display: block; margin-bottom: 4px; opacity: .8; }
#side_menu input, #side_menu select { margin: 0; }
#side_menu input[type="text"], #side_menu select { width: 100%; box-sizing: border-box; padding: 4px 6px; background: #161b24; color: inherit; border: 1px solid #2a3140; border-radius: 3px; font: inherit; }
#side_menu input[type="range"] { width: 100%; }
#side_menu .value { float: right; opacity: .7; }
#side_menu .note { min-height: 15px; font-size: 11px; color: #e0b050; }
#settings_b { position: absolute; right: 10px; bottom: 8px; width: 28px; height: 28px; stroke: #fff; fill: none; opacity: .55; cursor: pointer; }
#settings_b:hover { stroke: aqua; opacity: 1; }
#settings_b:active { stroke: darkmagenta; }
`;

/**
 * @param {object} opts
 * @param {{ setShadowsEnabled?: (on: boolean) => unknown, getShadowsEnabled?: () => boolean }} opts.renderer
 */
export function setupMenu({ renderer }) {
  // Shadow dimensions are locked in at renderer construction, so anything other
  // than the tier we booted with only takes effect on reload.
  const bootMode = resolveShadowMode();
  const bootTier = shadowTier(bootMode);

  const style = document.createElement('style');
  style.textContent = CSS;
  document.head.appendChild(style);

  const button = document.createElement('div');
  button.id = 'menu_b';
  button.title = 'Menu';
  button.innerHTML = ICON_BARS;

  const drawer = document.createElement('div');
  drawer.id = 'side_menu';
  drawer.innerHTML = `
    <div class="page is-active" data-page="main">
      <h2>Æther.Garden</h2>
      <div class="row" data-profile></div>
    </div>
    <div class="page" data-page="settings">
      <h2>Settings</h2>
      <div class="row">
        <label for="shadow_slider">Shadows <span class="value" id="shadow_value"></span></label>
        <input type="range" id="shadow_slider" min="0" max="${SHADOW_LABELS.length - 1}" step="1">
        <div class="note" id="shadow_note"></div>
      </div>
      <div class="row">
        <label for="name_input">Player name</label>
        <input type="text" id="name_input" maxlength="24" spellcheck="false" autocomplete="off">
      </div>
      <div class="row">
        <label for="color_picker">Colour</label>
        <select id="color_picker">
          ${PLAYER_COLORS.map((c) => `<option value="${c.hex}">${c.name}</option>`).join('')}
        </select>
      </div>
    </div>
    <div id="settings_b" title="Settings">${ICON_GEAR}</div>
  `;

  document.body.append(button, drawer);

  const pages = /** @type {NodeListOf<HTMLElement>} */ (drawer.querySelectorAll('.page'));
  const profile = /** @type {HTMLElement} */ (drawer.querySelector('[data-profile]'));
  const slider = /** @type {HTMLInputElement} */ (drawer.querySelector('#shadow_slider'));
  const sliderValue = /** @type {HTMLElement} */ (drawer.querySelector('#shadow_value'));
  const note = /** @type {HTMLElement} */ (drawer.querySelector('#shadow_note'));
  const nameInput = /** @type {HTMLInputElement} */ (drawer.querySelector('#name_input'));
  const colorPicker = /** @type {HTMLSelectElement} */ (drawer.querySelector('#color_picker'));
  const gear = /** @type {HTMLElement} */ (drawer.querySelector('#settings_b'));

  function showPage(name) {
    for (const page of pages) page.classList.toggle('is-active', page.dataset.page === name);
  }

  function paintProfile() {
    profile.textContent = getPlayerName();
    profile.style.color = getPlayerColor();
  }

  function paintShadow(mode) {
    sliderValue.textContent = SHADOW_LABELS[mode];
    const tier = shadowTier(mode);
    const needsReload = mode !== 0
      && (tier.mapSize !== bootTier.mapSize || tier.numCascades !== bootTier.numCascades);
    note.textContent = needsReload ? 'Reload to apply this quality.' : '';
  }

  slider.addEventListener('input', () => {
    const mode = setShadowMode(Number(slider.value));
    paintShadow(mode);
    // Off/on is the one part that can change live; the cascade count and map
    // size behind Low/Med/Full are baked into the depth texture at boot.
    renderer.setShadowsEnabled?.(mode !== 0);
  });

  nameInput.addEventListener('change', () => {
    nameInput.value = setPlayerName(nameInput.value);
    paintProfile();
  });

  colorPicker.addEventListener('change', () => {
    setPlayerColor(colorPicker.value);
    paintProfile();
  });

  // The camera and hotkeys listen on window with no target check, so typing a
  // name would otherwise pan the board and trip B/G/H.
  for (const field of [nameInput, colorPicker, slider]) {
    field.addEventListener('keydown', (e) => e.stopPropagation());
    field.addEventListener('keyup', (e) => e.stopPropagation());
  }

  function syncFromState() {
    // B toggles shadows outside the menu; reflect that rather than fighting it.
    const mode = renderer.getShadowsEnabled?.() === false ? 0 : getShadowMode();
    slider.value = String(mode);
    paintShadow(mode);
    nameInput.value = getPlayerName();
    colorPicker.value = getPlayerColor();
    paintProfile();
  }

  function setOpen(open) {
    drawer.classList.toggle('is-open', open);
    if (open) syncFromState();
  }

  button.addEventListener('click', () => setOpen(!drawer.classList.contains('is-open')));
  gear.addEventListener('click', () => {
    const onSettings = drawer.querySelector('.page.is-active')?.dataset.page === 'settings';
    showPage(onSettings ? 'main' : 'settings');
  });

  syncFromState();

  return {
    open: () => setOpen(true),
    close: () => setOpen(false),
    /** Keep the slider honest when shadows are toggled with B. */
    refresh: syncFromState,
  };
}
